intro = {'zh_CN': '\u7b80\u6d01\u7684\u65b0\u6807\u7b7e\u9875\uff1a\u81ea\u9002\u5e94\u4e66\u7b7e\u7f51\u683c\u3001\u9ad8\u6e05\u56fe\u6807\u3001\u62d6\u52a8\u6392\u5e8f\uff0c\u81ea\u52a8\u8ddf\u968f\u6df1\u6d45\u8272\u4e3b\u9898\u3002', 'zh_TW': '\u7c21\u6f54\u7684\u65b0\u5206\u9801\uff1a\u81ea\u9069\u61c9\u66f8\u7c64\u7db2\u683c\u3001\u6e05\u6670\u5716\u793a\u3001\u62d6\u66f3\u6392\u5e8f\uff0c\u81ea\u52d5\u8ddf\u96a8\u6dfa\u8272\u8207\u6df1\u8272\u4e3b\u984c\u3002', 'en': 'A clean new tab with a responsive bookmark grid, crisp icons, drag sorting, and automatic light and dark themes.', 'ja': '\u81ea\u52d5\u8abf\u6574\u306e\u30d6\u30c3\u30af\u30de\u30fc\u30af\u30b0\u30ea\u30c3\u30c9\u3001\u9ad8\u753b\u8cea\u30a2\u30a4\u30b3\u30f3\u3001\u30c9\u30e9\u30c3\u30b0\u4e26\u3079\u66ff\u3048\u3001\u30e9\u30a4\u30c8\u30fb\u30c0\u30fc\u30af\u8868\u793a\u306b\u5bfe\u5fdc\u3057\u305f\u30b7\u30f3\u30d7\u30eb\u306a\u65b0\u3057\u3044\u30bf\u30d6\u3002', 'ko': '\ubc18\uc751\ud615 \ubd81\ub9c8\ud06c \uadf8\ub9ac\ub4dc, \uc120\uba85\ud55c \uc544\uc774\ucf58, \ub4dc\ub798\uadf8 \uc815\ub82c, \uc790\ub3d9 \ub77c\uc774\ud2b8\xb7\ub2e4\ud06c \ud14c\ub9c8\ub97c \uc81c\uacf5\ud558\ub294 \uae54\ub054\ud55c \uc0c8 \ud0ed\uc785\ub2c8\ub2e4.'}
for (chromeLang, description) in intro.items():
    lang = 'zh' if chromeLang.startswith('zh') else chromeLang
    data = {'extensionName': {'message': 'Yiu\u2018s tab'}, 'extensionDescription': {'message': description}}
    data.update({key: {'message': value} for (key, value) in catalogs[lang].items() if not key.startswith('demo')})
    path = r / '_locales' / chromeLang / 'messages.json'
    path.parent.mkdir(exist_ok=True, parents=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2))
productionCatalogs = {lang: {key: value for (key, value) in entries.items() if not key.startswith('demo')} for (lang, entries) in catalogs.items()}
code = "\nconst UI_CATALOGS = CATALOGS;\nexport function resolveLanguage(value='en'){const base=String(value).toLowerCase().split(/[-_]/)[0];return Object.hasOwn(UI_CATALOGS,base)?base:'en';}\nlet currentLanguage=resolveLanguage(document.documentElement.dataset.previewLanguage||globalThis.chrome?.i18n?.getUILanguage?.()||navigator.language);\nexport function language(){return currentLanguage;}\nexport function t(key,params={}){const value=UI_CATALOGS[currentLanguage][key]??UI_CATALOGS.en[key]??key;return value.replace(/\\{(\\w+)\\}/g,(_,name)=>String(params[name]??'{'+name+'}'));}\nexport function uiError(key,params={}){const error=new Error(t(key,params));error.uiKey=key;error.uiParams=params;return error;}\nexport function setText(id,key,params={}){const el=document.getElementById(id);if(!el)return;if(!key){el.textContent='';delete el.dataset.messageKey;delete el.dataset.messageParams;return;}el.dataset.messageKey=key;el.dataset.messageParams=JSON.stringify(params);el.textContent=t(key,params);}\nexport function applyTranslations(root=document){document.documentElement.lang=currentLanguage==='zh'?'zh-CN':currentLanguage;for(const el of root.querySelectorAll('[data-i18n]'))el.textContent=t(el.dataset.i18n);for(const el of root.querySelectorAll('[data-i18n-aria]'))el.setAttribute('aria-label',t(el.dataset.i18nAria));for(const el of root.querySelectorAll('[data-i18n-title]'))el.title=t(el.dataset.i18nTitle);for(const el of root.querySelectorAll('[data-message-key]'))el.textContent=t(el.dataset.messageKey,JSON.parse(el.dataset.messageParams||'{}'));}\nexport function setLanguage(value){currentLanguage=resolveLanguage(value);applyTranslations();dispatchEvent(new CustomEvent('yiu-languagechange'));}\n".replace('CATALOGS;',
 json.dumps(productionCatalogs,
 ensure_ascii=False) + ';')
(r / 'newtab/js/i18n.js').write_text(code)
